		clock:      clock,
	}, nil
}

// AllowN reports whether n tokens are available and consumes them.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill()
	cost := float64(n)
	if l.tokens >= cost {
		l.tokens -= cost
		return true
	}
	return false
}

// Allow is shorthand for AllowN(1).
func (l *Limiter) Allow() bool { return l.AllowN(1) }

func (l *Limiter) refill() {
	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed <= 0 {
		return
	}
	l.tokens += elapsed * l.refillRate
	if l.tokens > l.capacity {
		l.tokens = l.capacity
	}
	l.last = now
}
